UPDATE organizations SET logo_url='https://jopvcsrmccoulujeyjvw.supabase.co/storage/v1/object/public/avatars/org-logos/riyadah-logo-v2.png' WHERE slug='riyadah' OR name ILIKE '%ريادة%';
